print(string_sequence(5))  # Output: '0 1 2 3 4 5'

def Strongest_Extension(class_name, extensions):
    def calculate_strength(extension):
        uppercase_count = sum(c.isupper() for c in extension)
        lowercase_count = sum(c.islower() for c in extension)
        return abs(uppercase_count - lowercase_count)

    strongest_extension = max(extensions, key=calculate_strength)
    return f"{class_name}.{strongest_extension}"

# Example usage:
print(Strongest_Extension('my_class', ['AA', 'Be', 'CC']))  # Output: 'my_class.AA'

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    if n <= 1:
        raise ValueError("Input must be greater than 1")

    for i in range(n, 0, -1):
        if n % i == 0:
            return i

# Example usage
print(largest_divisor(15))  # Output: 5

from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    """
    From a list of integers, remove all elements that occur more than once.
    Keep order of elements left the same as in the input.

    >>> remove_duplicates([1, 2, 3, 2, 4])
    [1, 3, 4]
    """
    # Create a dictionary to count occurrences of each number
    count_dict = {}
    for num in numbers:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    # Filter out numbers that occur more than once and preserve their order
    result = []
    seen = False
    for num in numbers:
        if count_dict[num] == 1:
            result.append(num)
            seen = True
        elif seen:
            continue  # Skip duplicates while keeping the order
        else:
            seen = True  # Mark that we have seen a non-duplicate

    return result

# Example usage
print(remove_duplicates([1, 2, 3, 2, 4]))  # Output: [1, 3, 4]

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    result = ""
    for char in string:
        if char.islower():
            result += char.upper()
        elif char.isupper():
            result += char.lower()
        else:
            result += char
    return result

